//refer:Bubble Chamber - Jared Tarbell, 2003
//http://www.complexification.net/gallery/machines/bubblechamber/

var p = [];
var q = [];
var mySize, margin;
var seed = Math.random() * 5017;
let colors1 = "fef9fb-fafdff-fcfbf4-f9f8f6".split("-").map((a) => "#" + a);
let colors2;
let colors_tone1 = "0D1E40-224573-5679A6-F2A25C-D96B43".split("-").map((a) => "#" + a);
let colors_tone2 = "7E56A6-F28B50-A63B14-591202-260101".split("-").map((a) => "#" + a);
let colors_tone3 = "4ED98A-3B8C57-F2AD85-404040-0D0D0D".split("-").map((a) => "#" + a);
let colors_tone4 = "725373-7866F2-8979F2-025373-BF7D56".split("-").map((a) => "#" + a);
let colors_tone5 = "20BF1B-218C11-17590C-11400A-0D0D0D".split("-").map((a) => "#" + a);
let colors_tone6 = "F20519-A60522-031059-071773-044BD9".split("-").map((a) => "#" + a);
let colors_tone7 = "F2E96D-F2B84B-BF8034-402B12-0D0D0D".split("-").map((a) => "#" + a);
let colors_tone8 = "9E9BF2-F2E088-F29544-F24405-F27E63".split("-").map((a) => "#" + a); // candy memory
let colors_tone9 = "323140-7B7DA6-BABCD9-BF8339-BFA18F".split("-").map((a) => "#" + a);

let colors_root = "362300-805300-402900-734E39".split("-").map((a) => "#" + a);

let colorset = [];
let colorbg = "202020-1a1a1a-282828".split("-").map((a) => "#" + a); // dark
let filter1;
let plusO, plus1;
let t, par_num;
let originalGraphics;
let lineGraphics;
let HighSpeedParticle_Graphics;
let ver;
var theta, STEP;

function setup() {
	frameRate(50);
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	// mySize = 1200;
	margin = mySize / 100;
	createCanvas(4/3*mySize, mySize);
	originalGraphics = createGraphics(width, height);
	lineGraphics = createGraphics(width, height);
	HighSpeedParticle_Graphics = createGraphics(width, height);

	for (let i = 0; i < 1; i++) {
		p[i] = createVector(width / 2, height / 2);
	}
	for (let i = 0; i < 30; i++) {
		q[i] = createVector(width / 2, height / 2);
	}
	// pixelDensity(3);
	colors2 = random([colors_tone1, colors_tone2, colors_tone3, colors_tone4, colors_tone5, colors_tone6, colors_tone7, colors_tone8, colors_tone9]);
	// colors2 = colors_tone9;
	colorset[0] = random(colors2);
	colorset[1] = random(colors2);
	colorset[2] = random(colors1);
	colorset[3] = random(colors2);
	colorset[4] = random(colors2);
	colorset[5] = random(colors2);
	// ver = random([1, 2]);
	ver = 2;
	if (ver == 1) {
		background("#fafdff");
	}
	if (ver == 2) {
		background("#202020");
	}
	filter1 = new makeFilter();
	plusO = plus1 = t = 0;
	theta = 0;
	STEP = 1 * PI * 0.0125; //曲線の精度

}

function draw() {
	randomSeed(seed);
	let verdraw = int(random(4, 3));

	//line
	par_num = random(400, 300);
	for (let i = 0; i <= par_num; i++) {
		lineGraphics.fill(str(random(colorset)) + "0d");
		lineGraphics.noStroke();
		if (frameCount % 2 == 0) {
			lineGraphics.stroke(str(random(colorset)) + "0d");
			lineGraphics.strokeWeight(random(0.25, 0.1));
			lineGraphics.noFill();
		}
		lineGraphics.drawingContext.shadowColor = str(random(colorbg)) + "1a";
		lineGraphics.drawingContext.shadowOffsetX = 1;
		lineGraphics.drawingContext.shadowOffsetY = 1;
		lineGraphics.drawingContext.shadowBlur = 0;

		const xAngle = map(0, 0, width, -random(0.5, 1) * PI, random(0.5, 1) * PI, true);
		const yAngle = map(height, 0, height, -random(0.5, 1) * PI, random(0.5, 1) * PI, true);
		const angle = xAngle * width + yAngle * height;

		const myX = width / 2 + mySize / 2 * sin(random(0.5, 1.5) * TAU * t + angle);
		const myY = height / 2 + mySize / 2 * cos(random(0.5, 1.5) * TAU * t + angle);

		lineGraphics.push();
		lineGraphics.translate(myX + sin(random(0.5, 1.5) * TAU * t + angle), myY + cos(random(0.5, 1.5) * TAU * t + angle));
		lineGraphics.rotate(sin(t) * PI / 10);
		lineGraphics.ellipse(0, 0, random(0.75, 1.25) * (1 - sqrt(random(random(1)))));
		lineGraphics.pop();
	}

	image(lineGraphics, 0, 0);
	t += random(0.005, 0.01);

	//originalGraphics
	originalGraphics.push();
	originalGraphics.translate(p[0].x, p[0].y);
	let gard_w = mySize / verdraw;
	let gard_h = gard_w;
	let r_max = 2 * gard_w;

	for (let i = 0; i < 5; i++) {
		originalGraphics.random(seed);
		originalGraphics.rotate(random(TAU));
		originalGraphics.fill(0);
		originalGraphics.noStroke();
		originalGraphics.blendMode(HARD_LIGHT);
		let speed_ratio1 = random(50, 10) / 725 * mySize;
		let speed_ratio2 = random(10, 5) / 725 * mySize;
		let grad = drawingContext.createRadialGradient(r_max / 2 - plus1 * speed_ratio2, r_max / 2 - plus1 * speed_ratio2, 0, r_max / 2 - plus1 * speed_ratio1, r_max / 2 - plus1 * speed_ratio1, r_max * 1 + plus1 * speed_ratio1);
		grad.addColorStop(random(0.05, 0.025), str(random(colorset)) + "00");
		grad.addColorStop(random(0.25, 0.15), str(random(colorset)) + "1a");
		grad.addColorStop(random(0.45, 0.65), str(random(colorset)) + "00");
		originalGraphics.drawingContext.fillStyle = grad;

		originalGraphics.drawingContext.shadowColor = str(random(colors1)) + "40";
		originalGraphics.drawingContext.shadowOffsetX = 1;
		originalGraphics.drawingContext.shadowOffsetY = 1;
		originalGraphics.drawingContext.shadowBlur = 0;
		originalGraphics.circle(0, 0, r_max);
	}
	originalGraphics.stroke(str(random(colorset)) + "80");
	originalGraphics.strokeWeight(random(0.5, 0.95) * (1 - sqrt(random(random(random(random()))))));
	originalGraphics.noFill();
	originalGraphics.drawingContext.setLineDash([1, 2, 2, 3]);
	originalGraphics.drawingContext.shadowColor = str(random(colorbg)) + "80";
	originalGraphics.drawingContext.shadowOffsetX = 1;
	originalGraphics.drawingContext.shadowOffsetY = 1;
	originalGraphics.drawingContext.shadowBlur = 0;
	originalGraphics.circle(0, 0, r_max);

	for (let i = 0; i < 2; i++) {
		originalGraphics.blendMode(BLEND);
		originalGraphics.push();
		originalGraphics.random(seed * i);
		originalGraphics.translate(random(100), random(100));
		originalGraphics.stroke(str(random(colorset)) + "40");
		originalGraphics.strokeWeight(random(0.5, 0.95) * (1 - sqrt(random(random(random(random()))))));
		originalGraphics.noFill();
		originalGraphics.drawingContext.setLineDash([1, 2, 2, 3]);
		originalGraphics.drawingContext.shadowColor = str(random(colorbg)) + "40";
		originalGraphics.drawingContext.shadowOffsetX = 1;
		originalGraphics.drawingContext.shadowOffsetY = 1;
		originalGraphics.drawingContext.shadowBlur = 0;
		originalGraphics.circle(0, 0, r_max * (1.25, 0.75));
		originalGraphics.pop();
	}
	originalGraphics.pop();

	//HighSpeedParticle_Graphics
	if (frameCount < 300) {
		randomSeed(seed);
		for (let newq of q) {
			let version = random(1, 10) * ver;
			let b1 = noise(newq.x / version, newq.y / version) * TWO_PI * 1;
			let c = random(1000, 500);

			// *** main point *** //
			b2 = (TWO_PI / c) * int((b1 / TWO_PI) * c) + c;
			newq.add(random(0.01, 0.005) * sin(b2), random(0.005, 0.01) * cos(b2));
			HighSpeedParticle_Graphics.push();
			HighSpeedParticle_Graphics.translate(newq.x, newq.y);
			HighSpeedParticle_Graphics.rotate(random(TAU));
			var gard_w = random(mySize / 0.35, mySize / 0.75) / ver;
			var gard_h = random(mySize / 0.35, mySize / 0.75) / ver;
			HighSpeedParticle_Graphics.stroke(random(colorset));
			HighSpeedParticle_Graphics.strokeWeight(random(1, 1.5) * (1 - sqrt(random(random(random()))) + theta / 100));
			HighSpeedParticle_Graphics.noFill();

			HighSpeedParticle_Graphics.drawingContext.shadowColor = str(random(colors1)) + "80";
			HighSpeedParticle_Graphics.drawingContext.shadowOffsetX = -1;
			HighSpeedParticle_Graphics.drawingContext.shadowOffsetY = -1;
			HighSpeedParticle_Graphics.drawingContext.shadowBlur = 0;

			HighSpeedParticle_Graphics.drawingContext.shadowColor = str(random(colorbg)) + "40";
			HighSpeedParticle_Graphics.drawingContext.shadowOffsetX = 1;
			HighSpeedParticle_Graphics.drawingContext.shadowOffsetY = 1;
			HighSpeedParticle_Graphics.drawingContext.shadowBlur = 0;
			HighSpeedParticle_Graphics.drawingContext.setLineDash([4, 8, 2, 5]);

			for (let k = 0; k < 1; k++) {
				HighSpeedParticle_Graphics.push();
				HighSpeedParticle_Graphics.translate(random(1.25, 0.5) * random(-gard_w, gard_w), random(1.25, 0.5) * random(-gard_h, gard_h));
				let r = (1 - sqrt(random(random(random())))) * (random(1, 2) * random(width, height) / random(128, 16));
				HighSpeedParticle_Graphics.stroke(str(random(colorset)) + "05");
				HighSpeedParticle_Graphics.noFill();
				let rad1 = sqrt(theta);
				let rad2 = sqrt(theta + STEP);
				let line_x1 = r * rad1 * cos(theta);
				let line_y1 = r * rad1 * sin(theta);
				let line_x2 = r * rad2 * cos(theta + STEP);
				let line_y2 = r * rad2 * sin(theta + STEP);
				HighSpeedParticle_Graphics.line(line_x1, line_y1, line_x2, line_y2);
				HighSpeedParticle_Graphics.pop();
			}

			HighSpeedParticle_Graphics.drawingContext.setLineDash([2, 4, 2, 5]);
			for (let k = 0; k < 1; k++) {
				HighSpeedParticle_Graphics.push();
				HighSpeedParticle_Graphics.translate(random(1.25, 0.5) * random(-gard_w, gard_w), random(1.25, 0.5) * random(-gard_h, gard_h));
				var r = (1 - sqrt(random(random(random())))) * (random(1, 2) * random(width, height) / random(2, 32));
				HighSpeedParticle_Graphics.stroke(str(random(colorset)) + "80");
				HighSpeedParticle_Graphics.noFill();
				var rad1 = sqrt(theta);
				var rad2 = sqrt(theta + STEP);
				var line_x1 = r / rad1 * cos(theta);
				var line_y1 = r / rad1 * sin(theta);
				var line_x2 = r / rad2 * cos(theta + STEP);
				var line_y2 = r / rad2 * sin(theta + STEP);
				HighSpeedParticle_Graphics.line(line_x1, line_y1, line_x2, line_y2);
				HighSpeedParticle_Graphics.pop();
			}

			HighSpeedParticle_Graphics.drawingContext.setLineDash([2, 4, 3, 5]);
			if (frameCount > 1) {
				for (let k = 0; k < 1; k++) {
					HighSpeedParticle_Graphics.drawingContext.shadowColor = str(random(colors1)) + "1a";
					HighSpeedParticle_Graphics.drawingContext.shadowOffsetX = random(-1, 1);
					HighSpeedParticle_Graphics.drawingContext.shadowOffsetY = random(-1, 1);
					HighSpeedParticle_Graphics.drawingContext.shadowBlur = 0;
					HighSpeedParticle_Graphics.push();
					HighSpeedParticle_Graphics.translate(random(1.75, 1) * random(-gard_w, gard_w), random(1.75, 1) * random(-gard_h, gard_h));
					HighSpeedParticle_Graphics.rotate(random(TAU));
					var r = (1 - sqrt(random(random(random())))) * (random(1, 2) * random(width, height) / random(32, 2));

					HighSpeedParticle_Graphics.stroke(str(random(colorset)) + "0d");
					HighSpeedParticle_Graphics.noFill();
					var rad1 = sqrt(1 - theta);
					var rad2 = sqrt(1 - (theta + STEP));
					var line_x1 = r / rad1 * cos(theta);
					var line_y1 = r / rad1 * sin(theta);
					var line_x2 = r / rad2 * cos(theta + STEP);
					var line_y2 = r / rad2 * sin(theta + STEP);
					HighSpeedParticle_Graphics.line(line_x1, line_y1, line_x2, line_y2);
					HighSpeedParticle_Graphics.pop();
				}

				for (let k = 0; k < 1; k++) {
					HighSpeedParticle_Graphics.push();
					HighSpeedParticle_Graphics.translate(random(1.75, 1) * random(-gard_w, gard_w), random(1.75, 1) * random(-gard_h, gard_h));
					var r = (1 - sqrt(random(random(random())))) * (random(1, 2) * random(width, height) / random(2, 32));

					HighSpeedParticle_Graphics.stroke(str(random(colorset)) + "40");
					HighSpeedParticle_Graphics.noFill();
					var angle = random(TWO_PI);
					var rad1 = pow(1, theta);
					var rad2 = pow(1, theta + STEP);
					var line_x1 = rad1 * cos(theta) * r;
					var line_y1 = rad1 * sin(theta) * r;
					var line_x2 = rad2 * cos(theta + STEP) * r;
					var line_y2 = rad2 * sin(theta + STEP) * r;
					HighSpeedParticle_Graphics.line(line_x1, line_y1, line_x2, line_y2);
					HighSpeedParticle_Graphics.pop();
				}

				for (let k = 0; k < 1; k++) {
					HighSpeedParticle_Graphics.drawingContext.shadowColor = str(random(colors1)) + "1a";
					HighSpeedParticle_Graphics.drawingContext.shadowOffsetX = random(-1, 1);
					HighSpeedParticle_Graphics.drawingContext.shadowOffsetY = random(-1, 1);
					HighSpeedParticle_Graphics.drawingContext.shadowBlur = 0;
					HighSpeedParticle_Graphics.push();
					HighSpeedParticle_Graphics.translate(random(1.75, 1) * random(-gard_w, gard_w), random(1.75, 1) * random(-gard_h, gard_h));
					HighSpeedParticle_Graphics.rotate(random(TAU));
					var r = (1 - sqrt(random(random(random())))) * (random(1, 2) * random(width, height) / random(2, 8));

					HighSpeedParticle_Graphics.stroke(str(random(colorset)) + "1a");
					HighSpeedParticle_Graphics.noFill();
					var rad1 = theta;
					var rad2 = theta + STEP;
					var line_x1 = r / rad1 * cos(theta);
					var line_y1 = r / rad1 * sin(theta);
					var line_x2 = r / rad2 * cos(theta + STEP);
					var line_y2 = r / rad2 * sin(theta + STEP);
					HighSpeedParticle_Graphics.line(line_x1, line_y1, line_x2, line_y2);
					HighSpeedParticle_Graphics.pop();
				}
			}
			HighSpeedParticle_Graphics.pop();
			plusO -= random(2, 3) * random(3, 2) * random(0.001, 0.00075) / 2;
			plus1 += random(2, 1) * random(3, 2) * random(0.001, 0.0005) / 10;
		}
	}

	theta += STEP * random(2, 3.5) * (1 - sqrt(random(random(random()))));
	//blendMode(BLEND);
	image(originalGraphics, 0, 0, width,height);
	image(HighSpeedParticle_Graphics, 0, 0, width,height);
	image(overAllTexture, 0, 0, width,height);

	if (frameCount == 300) {
		noLoop();
		blendMode(BLEND);
		image(overAllTexture, 0, 0);
		blendMode(SCREEN);
		strokeWeight(random(0.10, 0.2) / 2);
		stroke(str(random(colorset)) + "0d");
		noFill();
		drawingContext.setLineDash([1, 5, 1, 3]);
		drawOverPattern();
		drawingContext.setLineDash([1, 1, 1, 1]);
		blendMode(BLEND);

		noFill();
		strokeWeight(margin);
		rectMode(CORNER);
		stroke("#202020");
		rect(0, 0, width, height);
	}
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +
    ".jpg");
    lapse = millis();
  }
}

// === Tab: save & filter ===
	function keyTyped() {
		if (key === "s" || key === "S") {
			saveCanvas("1115_RE:BubbleChamber_17_2022", "png");
		}
	}

	//filter
	function makeFilter() {
		// noiseのフィルターをつくる
		colorMode(HSB, 360, 100, 100, 100);
		drawingContext.shadowColor = color(0, 0, 5, 95);
		overAllTexture = createGraphics(width, height);
		overAllTexture.loadPixels();
		for (var i = 0; i < width; i++) { // noprotect
			for (var j = 0; j < height; j++) {
				if( ver == 1 ){
				overAllTexture.set(i,j,
					color(0,0,random(95, 85),noise(i / 3, j / 3, (i * j) / 50) * random(5, 15) / 1));
				}
				if( ver == 2 ){
				overAllTexture.set(i,j,
					color(0,0,random(5, 10),noise(i / 3, j / 3, (i * j) / 50) * random(5, 15) / 1));
				}
			}
		}
		overAllTexture.updatePixels();
	}

	function drawOverPattern() {
		push();
		translate(width / 2, height / 2);
		rotate(-PI / 2);
		let s = mySize / 2 * sqrt(3) - 2;
		let n = 6;
		for (let theta = TWO_PI / 6; theta < TWO_PI; theta += TWO_PI / 6) { // noprotect
			divideOP(0, 0, s * cos(theta), s * sin(theta), s * cos(theta + TWO_PI / 6), s * sin(theta + TWO_PI / 6), n);
		}
		pop();
	}

	function prop(x1, y1, x2, y2, k) {
		let x3 = (1 - k) * x1 + k * x2;
		let y3 = (1 - k) * y1 + k * y2;
		return [x3, y3];
	}

	function divideOP(x1, y1, x2, y2, x3, y3, n) {
		if (n > 1) {
			let [xA, yA] = prop(x1, y1, x2, y2, 1 / 3);
			let [xB, yB] = prop(x1, y1, x2, y2, 2 / 3);
			let [xC, yC] = prop(x2, y2, x3, y3, 1 / 3);
			let [xD, yD] = prop(x2, y2, x3, y3, 2 / 3);
			let [xE, yE] = prop(x3, y3, x1, y1, 1 / 3);
			let [xF, yF] = prop(x3, y3, x1, y1, 2 / 3);
			let [xG, yG] = prop(xF, yF, xC, yC, 1 / 2);
			divideOP(x1, y1, xA, yA, xF, yF, n - 1);
			divideOP(xA, yA, xB, yB, xG, yG, n - 1);
			divideOP(xB, yB, x2, y2, xC, yC, n - 1);
			divideOP(xG, yG, xF, yF, xA, yA, n - 1);
			divideOP(xC, yC, xG, yG, xB, yB, n - 1);
			divideOP(xF, yF, xG, yG, xE, yE, n - 1);
			divideOP(xG, yG, xC, yC, xD, yD, n - 1);
			divideOP(xD, yD, xE, yE, xG, yG, n - 1);
			divideOP(xE, yE, xD, yD, x3, y3, n - 1);
		} else {
			makeTriangle([x1, y1], [x2, y2], [x3, y3]);
		}
	}

	function makeTriangle(v1, v2, v3) {
		let points = shuffle([v1, v2, v3]);
		let [x1, y1] = points[0];
		let [x2, y2] = points[1];
		let [x3, y3] = points[2];
		let iStep = 1 / (pow(2, floor(random(4, 2))));
		for (let i = 0; i < 1; i += iStep) { // noprotect
			let [x4, y4] = prop(x1, y1, x2, y2, 1 - i);
			let [x5, y5] = prop(x1, y1, x3, y3, 1 - i);
			triangle(x1, y1, x4, y4, x5, y5);
		}
	}

